/**
 * The presence user store: `~/.arcane/presence/` (ARC-060 decisions 2 and 6;
 * architecture D13, D14). It holds exactly two files:
 *
 * - `token`: 32 random bytes, base64url, generated by `serve` on first start
 *   and replaced by `--rotate`. Directory `0700`, file `0600` on POSIX; on
 *   Windows the file is restricted to the current account with `icacls`, and
 *   when that restriction fails the file is never left behind (ARC-054
 *   decision 3's rule, through `restrictToCurrentUser`, imported unchanged).
 * - `server.json`: the running service's URL, pid, port, start time and
 *   generator. Not a secret; written the same way so it is never half-written.
 *
 * Readers take the token from `ARCANE_PRESENCE_TOKEN` when it is set and
 * non-empty, else from the file. The variable wins even when it is wrong: the
 * file never silently rescues it. No function here takes a token from a
 * command line, and server.json never holds one.
 */

import { randomBytes } from "node:crypto";
import { chmodSync, existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { resolveRealPath } from "../real-path.js";
import { restrictToCurrentUser } from "../session-store.js";
import { resolveHomeDir, userTierRoot } from "../user-tier.js";
import { PRESENCE_ENV, type ServerInfo } from "./types.js";

export const PRESENCE_DIR_NAME = "presence";
/** Lowercase keys: the secrets scan reads an upper-case `...TOKEN... =` assignment as a credential. */
export const STORE_FILES = { token: "token", serverInfo: "server.json" } as const;

export interface StoreOptions {
  /** The home the store sits under. Defaults to the real one, resolved on every call. */
  home?: string;
  /** Restricts a file to the current account. Defaults to ARC-054's rule; a test injects a failure. */
  restrict?: (filePath: string) => void;
}

export class PresenceStoreError extends Error {}

function home(options: StoreOptions): string {
  return options.home ?? resolveHomeDir();
}

export function presenceDir(options: StoreOptions = {}): string {
  return join(userTierRoot(home(options)), PRESENCE_DIR_NAME);
}

export function tokenPath(options: StoreOptions = {}): string {
  return join(presenceDir(options), STORE_FILES.token);
}

export function serverInfoPath(options: StoreOptions = {}): string {
  return join(presenceDir(options), STORE_FILES.serverInfo);
}

/**
 * Creates the directory `0700` (and re-sets the mode every time), after
 * refusing a directory or a token that resolves, by real path, outside the
 * home's `.arcane` directory: a link there would move the token somewhere
 * this module does not control (ARC-057's rule applied to the store).
 */
export function ensureStore(options: StoreOptions = {}): string {
  const root = userTierRoot(home(options));
  const dir = presenceDir(options);
  mkdirSync(root, { recursive: true });
  const realRoot = resolveRealPath(root);
  if (relative(realRoot, resolveRealPath(dir)) !== PRESENCE_DIR_NAME) {
    throw new PresenceStoreError(`Refusing to use ${dir}: it resolves outside ${root}.`);
  }
  if (relative(realRoot, resolveRealPath(tokenPath(options))) !== join(PRESENCE_DIR_NAME, STORE_FILES.token)) {
    throw new PresenceStoreError(`Refusing to use ${tokenPath(options)}: it resolves outside ${dir}.`);
  }
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  chmodSync(dir, 0o700);
  return dir;
}

/** Temporary file created 0600, restricted, then renamed over the target. */
function writeRestricted(target: string, content: string, options: StoreOptions): void {
  const restrict = options.restrict ?? restrictToCurrentUser;
  const tmp = `${target}.${process.pid}.tmp`;
  writeFileSync(tmp, content, { encoding: "utf8", mode: 0o600 });
  try {
    restrict(tmp);
  } catch (error) {
    rmSync(tmp, { force: true });
    throw new PresenceStoreError(`Could not restrict ${target} to your account, so it was not written.`, { cause: error });
  }
  renameSync(tmp, target);
  chmodSync(target, 0o600);
}

export function generateToken(): string {
  return randomBytes(32).toString("base64url");
}

function readTokenFile(options: StoreOptions): string | null {
  let raw: string;
  try {
    raw = readFileSync(tokenPath(options), "utf8");
  } catch {
    return null;
  }
  const token = raw.replace(/[\r\n]+$/, "").trim();
  return token.length > 0 ? token : null;
}

/**
 * The service's token: the existing one (its mode re-set), or a new one when
 * there is none or `rotate` is set.
 */
export function ensureToken(options: StoreOptions & { rotate?: boolean } = {}): string {
  ensureStore(options);
  const existing = options.rotate === true ? null : readTokenFile(options);
  if (existing !== null) {
    chmodSync(tokenPath(options), 0o600);
    (options.restrict ?? restrictToCurrentUser)(tokenPath(options));
    return existing;
  }
  const token = generateToken();
  writeRestricted(tokenPath(options), `${token}\n`, options);
  return token;
}

/** `ARCANE_PRESENCE_TOKEN` when set and non-empty, else the file, else null. */
export function readToken(options: StoreOptions & { env?: NodeJS.ProcessEnv } = {}): string | null {
  const fromEnv = (options.env ?? process.env)[PRESENCE_ENV.token];
  if (fromEnv !== undefined && fromEnv.replace(/[\r\n]+$/, "") !== "") return fromEnv.replace(/[\r\n]+$/, "");
  return readTokenFile(options);
}

export function writeServerInfo(info: ServerInfo, options: StoreOptions = {}): void {
  ensureStore(options);
  writeRestricted(serverInfoPath(options), `${JSON.stringify(info, null, 2)}\n`, options);
}

/** The recorded service, or null when the file is absent or not one this module wrote. */
export function readServerInfo(options: StoreOptions = {}): ServerInfo | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(serverInfoPath(options), "utf8"));
  } catch {
    return null;
  }
  if (typeof parsed !== "object" || parsed === null) return null;
  const o = parsed as Record<string, unknown>;
  const generator = o["generator"] as Record<string, unknown> | null | undefined;
  const valid =
    typeof o["url"] === "string" &&
    Number.isInteger(o["pid"]) && (o["pid"] as number) > 0 &&
    Number.isInteger(o["port"]) && (o["port"] as number) >= 1 && (o["port"] as number) <= 65_535 &&
    typeof o["started_at"] === "string" &&
    typeof generator === "object" && generator !== null &&
    generator["name"] === "arcane-cli" && typeof generator["version"] === "string";
  if (!valid) return null;
  return {
    url: o["url"] as string,
    pid: o["pid"] as number,
    port: o["port"] as number,
    started_at: o["started_at"] as string,
    generator: { name: "arcane-cli", version: generator["version"] as string },
  };
}

export function removeServerInfo(options: StoreOptions = {}): void {
  rmSync(serverInfoPath(options), { force: true });
}

export function storeExists(options: StoreOptions = {}): boolean {
  return existsSync(presenceDir(options));
}
